export const unitIcon = (type) => ICONS[`u_${type}`] || null;
export const slotIcon = (slot) => ICONS[`r_${slot}`] || null;
export const techIcon = (id) => ICONS[`t_${id}`] || null;

export const ICON_AUTHORS = [...new Set(Object.values(ICONS).map((i) => i.by))]
  .sort((a, b) => a.localeCompare(b));

export const ICON_LICENCE =
  `Icons by ${ICON_AUTHORS.join(", ")} from game-icons.net, under CC BY 3.0.`;

export const featureIcon = (id) => ICONS[`f_${id}`] || null;
export const buildingIcon = (id) => ICONS[`b_${id}`] || null;
